const text={accepted:'Prospecto asignado. Ya puedes atenderlo.',already_assigned:'Este prospecto ya fue asignado.',expired:'La oferta ya vencio o pertenece a un turno anterior.',not_authorized:'Esta oferta no estaba dirigida a tu usuario.',delivery_pending:'La oferta aun no tiene entrega confirmada.'}[claim.claim_status]||'No fue posible procesar la aceptacion.';
