const trigger = $('When Called by WF1').first().json;
const claim   = $('Atomic Claim (WHERE status=open)').first().json;

const winner = {
  purpose: 'winner_confirmation',
  number: trigger.agent_phone,
  text: [
    `\u2705 Asignado! Lead: ${claim.lead_name || 'Sin nombre'}`,
    `\u{1F4F1} Telefono del lead: ${claim.lead_phone}`,
    `\u{1F3E0} Propiedad: ${claim.property_id}`,
    ``,
    `El asistente AI ya esta atendiendo sus preguntas. Te contactaremos si requiere tu intervencion (visita, negociacion, etc.).`
  ].join('\n')
};

const leadGreeting = {
  purpose: 'lead_greeting',
  number: claim.lead_phone,
  text: [
    `Hola${claim.lead_name ? ' ' + claim.lead_name.split(' ')[0] : ''}! \u{1F44B}`,
    ``,
    `Soy el asistente de la agencia. Estoy a tus ordenes para contarte sobre la propiedad. Que te gustaria saber? (precio, ubicacion, recamaras, amenidades, etc.)`,
    ``,
    `Hi${claim.lead_name ? ' ' + claim.lead_name.split(' ')[0] : ''}! I'm the agency assistant. I'm here to help you learn about this property. What would you like to know?`
  ].join('\n')
};

const losers = (claim.notified_agents || [])
  .filter(id => id !== trigger.agent_id)
  .map(agent_id => ({
    purpose: 'loser_notification',
    agent_id,
    text: `Este lead ya fue tomado por otro asesor. Suerte con el proximo! \u{1F4AA}`
  }));

return [winner, leadGreeting, ...losers].map(m => ({ json: m }));

